func TestChannelConfig_MaxBodyBytes(t *testing.T) {
	tests := []struct {
		input    string
		expected int64
	}{
		{"", 20 << 20},
		{"500B", 500},
		{"10KB", 10 * 1024},
		{"20MB", 20 * 1024 * 1024},
		{"1GB", 1 * 1024 * 1024 * 1024},
	}

	for _, tt := range tests {
		ch := &ChannelConfig{
			HTTP: HTTPConfig{MaxBodySize: tt.input},
		}
		if got := ch.MaxBodyBytes(); got != tt.expected {
			t.Errorf("MaxBodyBytes(%q) = %d; want %d", tt.input, got, tt.expected)
		}
	}
}

func TestConfig_ReloadChannels_WithEnvExpansion(t *testing.T) {
	tmpDir := t.TempDir()

	t.Setenv("TEST_CHANNEL_TOKEN", "super_secret_token_123")

	yamlContent := `
id: test_chan
name: "Test Channel"
http:
  allowed_methods: ["POST"]
  success_status: 200
  max_body_size: "15MB"
auth:
  type: "token"
  token: "${TEST_CHANNEL_TOKEN}"
`
	err := os.WriteFile(filepath.Join(tmpDir, "test_chan.yaml"), []byte(yamlContent), 0644)
	if err != nil {
		t.Fatalf("failed to create temp channel file: %v", err)
	}

	cfg := &Config{
		ChannelsDir: tmpDir,
		Channels:    make(map[string]*ChannelConfig),
	}

	if err := cfg.ReloadChannels(); err != nil {
		t.Fatalf("failed to reload channels: %v", err)
	}

	ch, exists := cfg.GetChannel("test_chan")
	if !exists {
		t.Fatalf("expected channel test_chan to exist")
	}

	if ch.Auth.Token != "super_secret_token_123" {
		t.Errorf("expected token expanded to super_secret_token_123, got %s", ch.Auth.Token)
	}

	if ch.MaxBodyBytes() != 15*1024*1024 {
		t.Errorf("expected 15MB in bytes, got %d", ch.MaxBodyBytes())
	}
}

